import "dart:convert";
import "dart:io";

import 'package:recase/recase.dart';

void main(List<String> args) {
  File fontsConfigFile = File(args[0]);

  if (!fontsConfigFile.existsSync()) {
    print('config file not found');
    exit(0);
  }

  String content = fontsConfigFile.readAsStringSync();
  List<dynamic> icons = json.decode(content);

  List<String> generatedOutput = [
    "library flutter_feather_icons_v2;\n",
    "import \"package:flutter/widgets.dart\";\n",
    "\n",
    "// THIS FILE IS AUTOMATICALLY GENERATED!\n"
    "// Based on flutter_feather_icons 2.0.0+1 by Nikhil Anand (MIT, https://github.com/muj-programmer/flutter_feather_icons).\n"
    "// Icons: Feather by Cole Bemis (MIT, https://feathericons.com).\n\n",
    "class FeatherIcons {\n"
  ];

  for (final dynamic item in icons) {
    final Map<String, dynamic> icon = item as Map<String, dynamic>;
    icon.forEach((String iconName, dynamic iconUnicode) => generatedOutput.add(
        "static const IconData ${ReCase(iconName).camelCase} = const IconData(0x$iconUnicode, fontFamily: \"FeatherIcons\", fontPackage: \"flutter_feather_icons_v2\");\n"));
  }

  generatedOutput.add("}\n");

  File output = File('./lib/flutter_feather_icons_v2.dart');
  output.writeAsStringSync(generatedOutput.join());
}
